{"command": "python3 << 'PYEOF'
import json
with open('/workspace/samples.json') as f:
    samples = json.load(f)

# Create ft2 batch file
batch = []
for inst_num, data in samples.items():
    batch.append({
        "name": "instrument_set",
        "arguments": {"instrument": inst_num, "name": data["name"]}
    })
    batch.append({
        "name": "sample_create_from_pcm",
        "arguments": {
            "instrument": inst_num,
            "sample": 0,
            "pcm": data["pcm"],
            "encoding": data["encoding"],
            "name": data["name"]
        }
    })
    # Set sample metadata - base note
    batch.append({
        "name": "sample_set",
        "arguments": {
            "instrument": inst_num,
            "sample": 0,
            "relative_note": data["base_note"] - 48,  # relative to C-4 (48)
            "volume": 64,
            "flags": 3  # loop enabled? Let's check - 1=loop, 2=pingpong, 3=both? Actually let's use 1 for forward loop
        }
    })

with open('/workspace/load_samples.json', 'w') as f:
    json.dump(batch, f)

print("Batch file created")
PYEOF
ft2 batch /workspace/load_samples.json"}

