{"command": "python3 << 'PYEOF'
# Let me first check current module info and set up pattern lengths
import subprocess, json

# Set all 16 patterns to 64 rows
for p in range(16):
    subprocess.run(['ft2', 'call', 'pattern_set_length', json.dumps({
        "pattern": p, "rows": 64
    })], capture_output=True)

print("Pattern lengths set")

# Set order - 16 patterns
for pos in range(16):
    subprocess.run(['ft2', 'call', 'order_set', json.dumps({
        "position": pos, "pattern": pos
    })], capture_output=True)

print("Order set")
PYEOF"}

